//! Demo page (rendered from the old src/index.js template string).
pub const PAGE: &str = r####"<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width"><title>agent-18 carrier-call agent</title><body style="font:15px system-ui;max-width:760px;margin:2em auto;padding:0 1em"><h1>agent-18 · Freight carrier-call agent (streaming)</h1><p>Load lookup → guardrailed rate negotiation → call summary, streamed as SSE. STT/TTS are <b>simulated with text</b>. <a href="https://github.com/braylo777/agent-18-voice-agent-latency">GitHub</a></p><textarea id=t rows=5 style="width:100%">Hey, calling on L1000, MC 123456
What's it paying?
I need $3000 all in
Can you do $2900</textarea><br><button onclick="go()">Run call</button> <span id=ms></span><pre id=o style="white-space:pre-wrap;background:#f4f4f4;padding:1em"></pre><script>async function go(){o.textContent='';const t0=performance.now();let first=0;const r=await fetch('/api/call',{method:'POST',body:JSON.stringify({utterances:t.value.split('\n')})});const rd=r.body.getReader(),d=new TextDecoder();for(;;){const{value,done}=await rd.read();if(done)break;if(!first){first=performance.now()-t0}o.textContent+=d.decode(value)}ms.textContent='first token '+first.toFixed(0)+' ms, total '+(performance.now()-t0).toFixed(0)+' ms'}</script>"####;
